"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["18620"],{73405(e){e.exports=JSON.parse('{"id":"V4-060","slug":"wealth-tax","term":"Wealth Tax","also_known_as":[],"difficulty":"Intermediate","definition":"A wealth tax is a tax charged regularly, usually each year, on the total value of a person\u2019s assets, such as property, investments and savings, minus their debts, above a certain threshold.","explanation":["Most taxes apply to income or spending. A wealth tax applies to the stock of assets a person owns. Supporters argue it can reduce wealth inequality and raise revenue from people whose wealth grows faster than their taxable income.","Several European countries once had wealth taxes, but many abolished them, citing difficulties valuing assets, administrative costs, capital flight and relatively low revenue. Countries that still have forms of wealth tax include Norway, Spain and Switzerland.","For example, a wealth tax of 1% on net wealth above 2,000,000 would charge a person with net wealth of 5,000,000 a tax of 30,000 a year.","Challenges include valuing assets that are not regularly traded, such as private businesses, art and land; the risk that wealthy people move to other countries; and the possibility that people must sell assets to pay the tax if their wealth is not producing much income. Debates about wealth taxes have revived in many countries as concerns about inequality have grown."],"note":"","total":1725,"prev":{"slug":"wealth-management","term":"Wealth Management"},"next":{"slug":"weighted-average","term":"Weighted Average"}}')}}]);